1	/**
2	 * Движок раундов — общий для HTTP-ядра и testkit.
3	 *
4	 * Операции движка написаны как генераторы: каждое обращение к кошельку — это `yield` операции
5	 * (`WalletOp`), в ответ генератор получает баланс после неё. Ошибку кошелька драйвер бросает
6	 * внутрь генератора. Testkit выполняет генератор синхронно с кошельком в памяти (`runSync`),
7	 * ядро — асинхронно с HTTP-кошельком (`runAsync`). Логика раунда при этом одна.
8	 *
9	 * Сохранность денег: раунд записывается в хранилище **до** списания ставки (признак `pendingBet`)
10	 * и до выплаты (поле `pendingPayout`). Если ответ кошелька не дошёл, следующая операция с этой игрой
11	 * досылает ту же транзакцию с тем же `txId` — кошелёк идемпотентен, поэтому повтор безопасен.
12	 */
13	import type { GameModule, Rng } from '../sdk/types.ts';
14	import { PlatformError, messageOf } from '../shared/errors.ts';
15	import { LIMITS, round2 } from '../shared/money.ts';
16	
17	/** Операция с кошельком, которую запрашивает движок. Результат — баланс после операции. */
18	export type WalletOp =
19	  | { kind: 'balance' }
20	  | { kind: 'bet' | 'payout'; txId: string; roundId: string; amount: number };
21	
22	/** Генератор операции движка: отдаёт `WalletOp`, получает баланс, возвращает `T`. */
23	export type EngineGen<T> = Generator<WalletOp, T, number>;
24	
25	/** Раунд в хранилище. Параметры и состояние игры хранятся в виде JSON. */
26	export interface RoundRecord {
27	  roundId: string;
28	  gameId: string;
29	  bet: number;
30	  params: unknown;
31	  state: unknown;
32	  status: 'open' | 'closed';
33	  /** Выплата закрытого раунда, `null` пока раунд открыт. */
34	  payout: number | null;
35	  /** Списание ставки отправлено, но кошелёк его ещё не подтвердил. */
36	  pendingBet?: boolean;
37	  /** Игра завершила раунд, но выплата ещё не подтверждена кошельком. */
38	  pendingPayout: number | null;
39	  /** Раунд аннулирован (ошибка игры на старте или недосланная ставка): ставка возвращена, `view` = `null`. */
40	  voided: boolean;
41	  /**
42	   * Игра упала после того, как взяла число из rng. Раунд остаётся открытым для ручного разбора:
43	   * ходы отклоняются с `INTERNAL_ERROR`, автоповтора и возврата ставки нет, `view` = `null`.
44	   */
45	  broken?: boolean;
46	}
47	
48	/** Ответ раунда — одинаковый у HTTP API и testkit. */
49	export interface RoundView {
50	  roundId: string;
51	  gameId: string;
52	  bet: number;
53	  status: 'open' | 'closed';
54	  view: unknown;
55	  payout: number | null;
56	  balance: number;
57	}
58	
59	/** Ответ открытия игры. */
60	export interface OpenResult {
61	  gameId: string;
62	  limits: { min: number; max: number };
63	  balance: number;
64	  activeRound: RoundView | null;
65	  /**
66	   * Раунд, который закрылся при этом открытии: досланная выплата или аннулированный раунд с недосланной ставкой.
67	   * Поля нет, если ничего не досылалось.
68	   */
69	  lastRound?: RoundView;
70	}
71	
72	/** Хранилище раундов. Методы синхронные; `get`/`findOpen` возвращают независимую копию. */
73	export interface RoundStore {
74	  get(roundId: string): RoundRecord | undefined;
75	  findOpen(gameId: string): RoundRecord | undefined;
76	  save(round: RoundRecord): void;
77	  /** Удаляет раунд, ставку которого кошелёк точно не списал. */
78	  delete(roundId: string): void;
79	}
80	
81	/** Настройки движка. */
82	export interface EngineOptions {
83	  games: GameModule[];
84	  store: RoundStore;
85	  rng: Rng;
86	  newRoundId: () => string;
87	}
88	
89	/** Движок раундов: лимиты, порядок проверок, вызовы игры, списание и выплата. */
90	export class RoundEngine {
91	  /** Подключённые игры по `id`. */
92	  readonly games: ReadonlyMap<string, GameModule>;
93	  readonly #store: RoundStore;
94	  readonly #rng: Rng;
95	  readonly #newRoundId: () => string;
96	
97	  /** @param opts игры, хранилище раундов, rng и генератор идентификаторов раундов */
98	  constructor(opts: EngineOptions) {
99	    const games = new Map<string, GameModule>();
100	    for (const g of opts.games) {
101	      if (!g || typeof g.id !== 'string') throw new TypeError('game module must have a string id');
102	      if (games.has(g.id)) throw new TypeError(`duplicate game id: ${g.id}`);
103	      games.set(g.id, g);
104	    }
105	    this.games = games;
106	    this.#store = opts.store;
107	    this.#rng = opts.rng;
108	    this.#newRoundId = opts.newRoundId;
109	  }
110	
111	  /**
112	   * Открытие игры: лимиты, баланс и незавершённый раунд.
113	   * Досылает недошедшие ставку или выплату; закрытый при этом раунд возвращается в `lastRound`.
114	   */
115	  *open(gameId: string): EngineGen<OpenResult> {
116	    this.#game(gameId);
117	    let last: RoundRecord | null = null;
118	    try {
119	      last = yield* this.#recover(gameId);
120	    } catch (e) {
121	      // Кошелёк окончательно отклонил досылку (не сбой связи): раунд остаётся ждать ручного разбора,
122	      // но open всё равно отдаёт лимиты, баланс и этот раунд с `view: null`, а не блокирует игру ошибкой.
123	      if (isUncertain(e)) throw e;
124	      const detail = e instanceof PlatformError ? `${e.code}: ${detailOf(e)}` : messageOf(e);
125	      console.error(`Досылка операции раунда игры ${gameId} отклонена кошельком, нужен ручной разбор: ${detail}`);
126	    }
127	    const round = this.#store.findOpen(gameId);
128	    const balance: number = yield { kind: 'balance' };
129	    const result: OpenResult = {
130	      gameId,
131	      limits: { min: LIMITS.min, max: LIMITS.max },
132	      balance,
133	      activeRound: round ? this.#view(round, balance, true) : null,
134	    };
135	    if (last) result.lastRound = this.#view(last, balance, true);
136	    return result;
137	  }
138	
139	  /**
140	   * Новый раунд. Порядок проверок: игра → лимиты → параметры → досылка недошедших операций → открытый раунд
141	   * → сохранение раунда → списание → `start`. Кошелёк не вызывается, пока не пройдены все проверки без денег.
142	   */
143	  *startRound(gameId: string, bet: unknown, params: unknown): EngineGen<RoundView> {
144	    const game = this.#game(gameId);
145	    const amount = checkBet(bet);
146	    const p = toJson(callGame(() => game.validateParams(params), 'INVALID_PARAMS'));
147	    yield* this.#recover(gameId);
148	    if (this.#store.findOpen(gameId)) throw new PlatformError('ROUND_ALREADY_OPEN');
149	
150	    const roundId = this.#newRoundId();
151	    const round: RoundRecord = {
152	      roundId,
153	      gameId,
154	      bet: amount,
155	      params: p,
156	      state: null,
157	      status: 'open',
158	      payout: null,
159	      pendingBet: true,
160	      pendingPayout: null,
161	      voided: false,
162	    };
163	    // Раунд записан до списания: если ответ кошелька потеряется, ставку можно будет дослать и вернуть.
164	    this.#store.save(round);
165	    let afterBet: number;
166	    try {
167	      afterBet = yield { kind: 'bet', txId: `${roundId}:bet`, roundId, amount };
168	    } catch (e) {
169	      if (!isUncertain(e)) this.#store.delete(roundId);
170	      throw e;
171	    }
172	    round.pendingBet = false;
173	
174	    let step: unknown;
175	    let state: unknown;
176	    const rng = guardedRng(this.#rng);
177	    try {
178	      step = game.start({ bet: amount, params: toJson(p), rng: rng.rng });
179	      if (isValidStep(step)) state = toJson(step.state);
180	    } catch (e) {
181	      const err = internal(`Игра ${game.id} не смогла начать раунд: ${detailOf(e)}`);
182	      if (rng.used()) {
183	        // Исход уже разыгран: возврат ставки дал бы бесплатный переброс. Раунд ждёт ручного разбора.
184	        this.#markBroken(round, err);
185	        throw err;
186	      }
187	      // Игра упала до розыгрыша: состояния нет, продолжать нельзя — аннулируем и возвращаем ставку.
188	      round.voided = true;
189	      yield* this.#settle(round, amount);
190	      throw err;
191	    }
192	    if (!isValidStep(step)) {
193	      // Ставка уже списана: раунд остаётся открытым с тем, что вернула игра (PL-19, D-023).
194	      round.state = safeJson((step as { state?: unknown } | null)?.state);
195	      const err = internal(`Игра ${game.id} вернула некорректный шаг на старте`);
196	      // Исход уже разыгран: ходы по такому состоянию заблокированы до ручного разбора (D-046).
197	      if (rng.used()) this.#markBroken(round, err);
198	      else this.#store.save(round);
199	      throw err;
200	    }
201	    return yield* this.#apply(round, step, state, afterBet);
202	  }
203	
204	  /** Ход в открытом раунде. При `INVALID_ACTION` и ошибке игры состояние раунда и баланс не меняются. */
205	  *action(roundId: string, action: unknown): EngineGen<RoundView> {
206	    const round = this.#store.get(roundId);
207	    if (!round) throw new PlatformError('ROUND_NOT_FOUND');
208	    if (round.status === 'closed') throw new PlatformError('ROUND_CLOSED');
209	    const game = this.games.get(round.gameId);
210	    if (!game) throw internal(`Игра ${round.gameId} не подключена`);
211	    if (round.pendingBet === true) {
212	      // Списание не подтверждено, игра не начиналась: досылаем ставку и аннулируем раунд.
213	      const closed = yield* this.#retryBet(round);
214	      throw new PlatformError(closed ? 'ROUND_CLOSED' : 'ROUND_NOT_FOUND');
215	    }
216	    if (round.pendingPayout !== null) {
217	      // Игра уже завершила раунд, ждём только выплату — досылаем её, ходить больше нельзя.
218	      yield* this.#settle(round, round.pendingPayout);
219	      throw new PlatformError('ROUND_CLOSED');
220	    }
221	    if (round.broken === true) throw internal(`Раунд ${round.roundId} игры ${game.id} ждёт ручного разбора`);
222	    const rng = guardedRng(this.#rng);
223	    let step: { status: 'continue'; state: unknown } | { status: 'finished'; state: unknown; payout: number };
224	    let state: unknown;
225	    try {
226	      const s = callGame(
227	        () => game.action({ bet: round.bet, params: round.params, state: round.state, action, rng: rng.rng }),
228	        'INVALID_ACTION',
229	      );
230	      if (!isValidStep(s)) throw internal(`Игра ${game.id} вернула некорректный шаг`);
231	      step = s;
232	      state = toJson(step.state);
233	    } catch (e) {
234	      // До обращения к rng ошибка безопасна: ход можно повторить. После — повтор хода дал бы новый исход,
235	      // поэтому раунд блокируется для ручного разбора (контракт: игра проверяет ход до rng, D-046).
236	      if (!rng.used()) throw e;
237	      const err = internal(`Игра ${game.id} упала после розыгрыша в раунде ${round.roundId}: ${detailOf(e)}`);
238	      this.#markBroken(round, err);
239	      throw err;
240	    }
241	    return yield* this.#apply(round, step, state, null);
242	  }
243	
244	  /** Помечает раунд сломанным и пишет причину в серверный лог. */
245	  #markBroken(round: RoundRecord, err: PlatformError): void {
246	    round.broken = true;
247	    this.#store.save(round);
248	    console.error(`${err.code}: ${err.detail ?? ''} — раунд ${round.roundId} заблокирован, нужен ручной разбор`);
249	  }
250	
251	  /** Досылает недошедшие ставку или выплату открытого раунда игры. Возвращает раунд, если он при этом закрылся. */
252	  *#recover(gameId: string): EngineGen<RoundRecord | null> {
253	    const round = this.#store.findOpen(gameId);
254	    if (!round) return null;
255	    if (round.pendingBet === true) return yield* this.#retryBet(round);
256	    if (round.pendingPayout !== null) {
257	      yield* this.#settle(round, round.pendingPayout);
258	      return round;
259	    }
260	    return null;
261	  }
262	
263	  /**
264	   * Повторяет списание ставки с тем же `txId`. Если кошелёк его провёл — раунд аннулируется со возвратом ставки
265	   * (игра ещё не начиналась) и возвращается закрытым. Если кошелёк точно отказал — запись удаляется, результат `null`.
266	   * Если кошелёк снова не ответил — ошибка пробрасывается, раунд остаётся в ожидании.
267	   */
268	  *#retryBet(round: RoundRecord): EngineGen<RoundRecord | null> {
269	    try {
270	      yield { kind: 'bet', txId: `${round.roundId}:bet`, roundId: round.roundId, amount: round.bet };
271	    } catch (e) {
272	      if (isUncertain(e)) throw e;
273	      this.#store.delete(round.roundId);
274	      return null;
275	    }
276	    round.pendingBet = false;
277	    round.voided = true;
278	    yield* this.#settle(round, round.bet);
279	    return round;
280	  }
281	
282	  /** Применяет корректный шаг игры: сохраняет состояние, а на `finished` — выплачивает и закрывает раунд. */
283	  *#apply(
284	    round: RoundRecord,
285	    step: { status: 'continue' } | { status: 'finished'; payout: number },
286	    state: unknown,
287	    knownBalance: number | null,
288	  ): EngineGen<RoundView> {
289	    round.state = state;
290	    if (step.status === 'continue') {
291	      this.#store.save(round);
292	      const balance: number = knownBalance ?? (yield { kind: 'balance' });
293	      return this.#view(round, balance, false);
294	    }
295	    const balance = yield* this.#settle(round, round2(step.payout));
296	    return this.#view(round, balance, false);
297	  }
298	
299	  /** Выплата `<roundId>:payout` и закрытие раунда. До ответа кошелька раунд сохранён как «ждёт выплаты». */
300	  *#settle(round: RoundRecord, amount: number): EngineGen<number> {
301	    round.pendingPayout = amount;
302	    this.#store.save(round);
303	    const balance: number = yield { kind: 'payout', txId: `${round.roundId}:payout`, roundId: round.roundId, amount };
304	    round.status = 'closed';
305	    round.payout = amount;
306	    round.pendingPayout = null;
307	    this.#store.save(round);
308	    return balance;
309	  }
310	
311	  /**
312	   * Ответ раунда. Если `publicView` игры падает, а раунд уже закрыт или ответ нужен для `open`,
313	   * отдаётся `view: null`, чтобы сломанное отображение не блокировало игру и не прятало итог раунда.
314	   */
315	  #view(round: RoundRecord, balance: number, safe: boolean): RoundView {
316	    let view: unknown = null;
317	    // Раунд, ждущий выплаты, игра уже завершила: ходов нет, показывать нечего до закрытия.
318	    if (!round.voided && round.broken !== true && round.pendingBet !== true && round.pendingPayout === null) {
319	      try {
320	        const game = this.games.get(round.gameId);
321	        if (!game) throw new Error(`Игра ${round.gameId} не подключена`);
322	        view = toJson(game.publicView(round.state, round.status === 'closed'));
323	      } catch (e) {
324	        const err = internal(`Игра ${round.gameId} не смогла показать раунд ${round.roundId}: ${detailOf(e)}`);
325	        if (!safe && round.status === 'open') throw err;
326	        console.error(`${err.code}: ${err.detail}`);
327	        view = null;
328	      }
329	    }
330	    return { roundId: round.roundId, gameId: round.gameId, bet: round.bet, status: round.status, view, payout: round.payout, balance };
331	  }
332	
333	  #game(gameId: unknown): GameModule {
334	    const game = typeof gameId === 'string' ? this.games.get(gameId) : undefined;
335	    if (!game) throw new PlatformError('GAME_NOT_FOUND');
336	    return game;
337	  }
338	}
339	
340	/**
341	 * Отдельный замороженный rng на один вызов игры. Игра не получает генератор платформы и не может подменить
342	 * его `next` для следующих раундов. Число вне [0, 1) — `INTERNAL_ERROR`. `used()` — брала ли игра число.
343	 */
344	function guardedRng(source: Rng): { rng: Rng; used: () => boolean } {
345	  let count = 0;
346	  const rng: Rng = Object.freeze({
347	    next: (): number => {
348	      const v = source.next();
349	      if (typeof v !== 'number' || !(v >= 0 && v < 1)) throw internal(`rng вернул число вне [0, 1): ${String(v)}`);
350	      count += 1;
351	      return v;
352	    },
353	  });
354	  return { rng, used: () => count > 0 };
355	}
356	
357	/** Ставка: конечное число, округлённое до центов и попадающее в лимиты. Иначе `BET_OUT_OF_LIMITS`. */
358	function checkBet(bet: unknown): number {
359	  if (typeof bet !== 'number' || !Number.isFinite(bet)) throw new PlatformError('BET_OUT_OF_LIMITS');
360	  const amount = round2(bet);
361	  if (amount < LIMITS.min || amount > LIMITS.max) throw new PlatformError('BET_OUT_OF_LIMITS');
362	  return amount;
363	}
364	
365	/** `INTERNAL_ERROR` со стандартным сообщением для клиента; подробности — только для серверного лога. */
366	function internal(detail: string): PlatformError {
367	  return new PlatformError('INTERNAL_ERROR', undefined, detail);
368	}
369	
370	function detailOf(e: unknown): string {
371	  return e instanceof PlatformError && e.detail !== undefined ? e.detail : messageOf(e);
372	}
373	
374	/**
375	 * Ошибка кошелька, после которой неизвестно, провёл ли он операцию (нет ответа, таймаут, 5xx).
376	 * Точные отказы (`INSUFFICIENT_FUNDS`, отклонённый запрос) неопределённости не оставляют.
377	 */
378	function isUncertain(e: unknown): boolean {
379	  if (!(e instanceof PlatformError)) return true;
380	  return e.code === 'WALLET_UNAVAILABLE';
381	}
382	
383	/** Вызов игры: ожидаемый код (`INVALID_PARAMS`/`INVALID_ACTION`) пробрасывается, остальное — `INTERNAL_ERROR`. */
384	function callGame<T>(fn: () => T, expected: 'INVALID_PARAMS' | 'INVALID_ACTION'): T {
385	  try {
386	    return fn();
387	  } catch (e) {
388	    const code = (e as { code?: unknown } | null)?.code;
389	    if (code === expected) {
390	      const msg = e instanceof Error && e.message && e.message !== expected ? e.message : undefined;
391	      throw new PlatformError(expected, msg);
392	    }
393	    throw internal(`Ошибка игры: ${messageOf(e)}`);
394	  }
395	}
396	
397	function isValidStep(step: unknown): step is { status: 'continue'; state: unknown } | { status: 'finished'; state: unknown; payout: number } {
398	  if (!step || typeof step !== 'object') return false;
399	  const s = step as { status?: unknown; payout?: unknown };
400	  if (s.status === 'continue') return true;
401	  return s.status === 'finished' && typeof s.payout === 'number' && Number.isFinite(s.payout) && s.payout >= 0;
402	}
403	
404	/** Копия значения через JSON — так же, как оно переживёт хранение на диске. */
405	function toJson<T>(value: T): T {
406	  if (value === undefined) return value;
407	  try {
408	    return JSON.parse(JSON.stringify(value)) as T;
409	  } catch (e) {
410	    throw internal(`Состояние игры не сериализуется в JSON: ${messageOf(e)}`);
411	  }
412	}
413	
414	function safeJson(value: unknown): unknown {
415	  try {
416	    return toJson(value);
417	  } catch {
418	    return null;
419	  }
420	}
421	
422	/** Выполняет операцию движка синхронно. `exec` выполняет операцию кошелька или бросает ошибку. */
423	export function runSync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => number): T {
424	  let r = gen.next();
425	  while (!r.done) {
426	    let balance: number;
427	    try {
428	      balance = exec(r.value);
429	    } catch (e) {
430	      r = gen.throw(e);
431	      continue;
432	    }
433	    r = gen.next(balance);
434	  }
435	  return r.value;
436	}
437	
438	/** Выполняет операцию движка асинхронно (кошелёк по HTTP). */
439	export async function runAsync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => Promise<number>): Promise<T> {
